#include "tracker.h"
#include <stdlib.h>
int tracker_run(const SimulationResult*s,const KalmanConfig*c,EstimateSample**out,size_t*n){if(!s||!c||!out||!n||s->dt<=0)return -1;*out=calloc(s->truth_count,sizeof**out);if(!*out)return -1;*n=0;KalmanFilter f;if(kalman_init(&f,c)!=KF_OK){free(*out);return -1;}size_t gi=0;for(size_t i=0;i<s->truth_count;i++){const TruthSample*t=&s->truth[i];while(gi<s->gps_count&&s->gps[gi].step<t->step)gi++;const GpsMeasurement*g=(gi<s->gps_count&&s->gps[gi].step==t->step)?&s->gps[gi]:NULL;if(f.initialized&&t->step>0&&kalman_predict(&f,s->dt)!=KF_OK)goto fail;bool used=false;if(g&&g->valid){if(!f.initialized){kalman_initialize(&f,g->pos.x,g->pos.y,0,0);used=true;}else used=kalman_update(&f,g->pos.x,g->pos.y)==KF_OK;}if(f.initialized)(*out)[(*n)++]=(EstimateSample){t->step,t->t,{f.x[0],f.x[1]},{f.x[2],f.x[3]},kalman_position_std(&f),used};}return 0;fail:free(*out);*out=NULL;*n=0;return -1;}
